-- Synthetic fixtures only; run in PGlite, never in production.
begin;
insert into public.products(id,name,sku,active) values('b1000000-0000-4000-8000-000000000001','Old name','e-hp-wd-0001',false);
insert into vault.decrypted_secrets values('b1000000-0000-4000-8000-000000000099',repeat('c',64));
update private.pim_connection set enabled=true,sync_token_digest=repeat('a',64),source_secret_id='b1000000-0000-4000-8000-000000000099';
do $$declare claim jsonb; snap jsonb; row1 jsonb; result jsonb; old_time timestamptz;before_count int;begin
 assert not has_function_privilege('anon','public.pim_sync_begin(text)','execute');
 assert not has_function_privilege('authenticated','public.pim_sync_finish(uuid,jsonb)','execute');
 assert not has_table_privilege('authenticated','private.pim_connection','select');
 assert not has_function_privilege('authenticated','private.queue_pim_sync()','execute');
 begin perform private.pim_sync_begin(repeat('b',64));raise exception 'FAIL bad token';exception when insufficient_privilege then null;end;
 claim=private.pim_sync_begin(repeat('a',64));assert claim->>'source_token'=repeat('c',64);
 assert private.pim_sync_begin(repeat('a',64)) is null,'overlapping sync rejected';
 row1=jsonb_build_object('variant_id','b2000000-0000-4000-8000-000000000001','product_id','b3000000-0000-4000-8000-000000000001','sku','E-HP-WD-0001','name','Updated name','available',true,'image_url',null,'image_key',null,'image_expires_at',null);
 snap=jsonb_build_object('schema_version',1,'source_project','caikfzxvlyzmqvgpvgye','complete',true,'snapshot_at',clock_timestamp(),'rows',jsonb_build_array(row1));
 begin perform private.pim_sync_finish(gen_random_uuid(),snap);raise exception 'FAIL lease mismatch';exception when insufficient_privilege then null;end;
 result=private.pim_sync_finish((claim->>'lease')::uuid,snap);
 assert result->>'matched'='1' and result->>'added'='0','same SKU retains identity';
 assert exists(select 1 from public.products where id='b1000000-0000-4000-8000-000000000001' and name='Updated name' and not active and pim_available and pim_variant_id=(row1->>'variant_id')::uuid),'local availability and ID retained';
 select updated_at into old_time from public.products where id='b1000000-0000-4000-8000-000000000001';
 update private.pim_connection set last_attempt=null;claim=private.pim_sync_begin(repeat('a',64));
 snap=jsonb_set(snap,'{snapshot_at}',to_jsonb(greatest(clock_timestamp(),(snap->>'snapshot_at')::timestamptz+interval '1 microsecond')));
 result=private.pim_sync_finish((claim->>'lease')::uuid,snap);
 assert result->>'unchanged'='1';assert (select updated_at=old_time from public.products where id='b1000000-0000-4000-8000-000000000001');
 update private.pim_connection set last_attempt=null;claim=private.pim_sync_begin(repeat('a',64));
 select count(*) into before_count from public.products;
 begin perform private.pim_sync_finish((claim->>'lease')::uuid,jsonb_set(snap,'{complete}','false'));raise exception 'FAIL partial feed';exception when invalid_parameter_value then null;end;
 begin perform private.pim_sync_finish((claim->>'lease')::uuid,snap);raise exception 'FAIL stale feed';exception when serialization_failure then null;end;
 snap=jsonb_set(snap,'{snapshot_at}',to_jsonb(greatest(clock_timestamp(),(snap->>'snapshot_at')::timestamptz+interval '1 microsecond')));
 begin perform private.pim_sync_finish((claim->>'lease')::uuid,jsonb_set(snap,'{rows}',jsonb_build_array(row1,row1)));raise exception 'FAIL duplicate';exception when invalid_parameter_value then null;end;
 assert (select count(*)=before_count from public.products),'invalid feed atomic';
 row1=jsonb_set(row1,'{available}','false');snap=jsonb_set(snap,'{rows}',jsonb_build_array(row1));
 result=private.pim_sync_finish((claim->>'lease')::uuid,snap);
 assert (select not pim_available from public.products where id='b1000000-0000-4000-8000-000000000001'),'archived row retained but unavailable';
 perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
 begin update public.products set name='Not allowed' where id='b1000000-0000-4000-8000-000000000001';raise exception 'FAIL managed details';exception when insufficient_privilege then null;end;
 update public.products set active=true where id='b1000000-0000-4000-8000-000000000001';
 perform set_config('request.jwt.claims','{}',true);
 update private.pim_connection set last_attempt=null;claim=private.pim_sync_begin(repeat('a',64));
 perform private.pim_sync_fail((claim->>'lease')::uuid);
 assert (select last_error is not null and lease is null from private.pim_connection),'failure releases lease and retains catalog';
 update private.pim_connection set last_attempt=null,enabled=false;
 assert private.pim_sync_begin(repeat('a',64)) is null,'paused sync';
end $$;
rollback;
select 'PASS: PIM catalog sync';
